        maxDamageFractionPerHit: undefined,
        reversesNextDamage: undefined,
        extraStrikesPerHit: 0,
        spellRechargeFaster: 0,
        bindingRitualRechargeFaster: 0,
        incomingHexCastTimeMultiplier: 1,
