/**
 * Units in one strike of adrenaline (GW1, #463). A skill's adrenaline cost
 * is in strikes, a blow that lands gives one, and a skill's pool holds
 * units. A rule, not a tunable.
 */
export const ADRENALINE_PER_STRIKE = 25;
